import{_ as t,o as r,c as n,a3 as i}from"./chunks/framework.z_KJ15Ep.js";const a="/bilder/sekundarstufen/verwaltung-export-abiturdaten.png",b=JSON.parse('{"title":"Abiturdaten als Textdatei exportieren","description":"","frontmatter":{"title":"Abiturdaten als Textdatei exportieren","source_pageid":1175,"source_revision":3953},"headers":[],"relativePath":"zeugnisse/sekundarstufen/abiturdaten-verwaltung-export.md","filePath":"zeugnisse/sekundarstufen/abiturdaten-verwaltung-export.md"}'),d={name:"zeugnisse/sekundarstufen/abiturdaten-verwaltung-export.md"};function s(u,e,o,l,p,g){return r(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="abiturdaten-als-textdatei-exportieren" tabindex="-1">Abiturdaten als Textdatei exportieren <a class="header-anchor" href="#abiturdaten-als-textdatei-exportieren" aria-label="Permalink to &quot;Abiturdaten als Textdatei exportieren&quot;">​</a></h1><p>Erstellen Sie AbiturExport.txt im gewählten Zielordner. Für jedes Abiturfach wird eine eigene Datenzeile ausgegeben.</p><p><a href="/bilder/sekundarstufen/verwaltung-export-abiturdaten.png"><img src="'+a+`" alt="Exportieren Sie die Abiturdaten in eine Textdatei über Verwaltung ➜ Export ➜ Abiturdaten." loading="lazy"></a></p><p><em>Exportieren Sie die Abiturdaten in eine Textdatei über Verwaltung ➜ Export ➜ <strong>Abiturdaten</strong>.</em></p><p>Über <em>Verwaltung ➜ Export</em> ➜ <strong>Abiturdaten</strong> lässt sich eine Textdatei mit den Daten zum aktuellen Abitur erzeugen.</p><p>Hierzu ist ein <strong>Ausgabeverzeichnis</strong> zu wählen.</p><p>Klicken Sie dann auf <code>Daten exportieren</code>. Hierbei werden existierende Daten überschrieben, die diesbezügliche Meldung ist mit <code>OK</code> zu bestätigen.</p><p>In diesem Ordner wird eine Datei <em>AbiturExport.txt</em> erzeugt, in der die Kopfzeile wie folgt aussieht und damit in den Folgezeilen auch die entsprechenden Informationen enthält.</p><pre><code> SchulNR;SchuelerNr;Geschlecht;Fach;Kursart;Fremdspr_fortgef;Vornote;PruefNote;AbiNote;Bestanden;PruefOrdn;SGL
</code></pre><p>Es wird für jedes Abiturfach eine eigene Zeile erzeugt.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Abiturdaten_(Verwaltung_Export)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 3953.</p>`,12)])])}const x=t(d,[["render",s]]);export{b as __pageData,x as default};
